from datetime import date, timedelta


def recur(start: str, rule: str, count: int) -> list[str]:
    year, month, day = (int(part) for part in start.split("-"))
    start_date = date(year, month, day)
    parts = rule.split(" ")
    kind = parts[0]
    step = int(parts[1])

    if kind == "DAILY":
        return _daily(start_date, step, count)
    if kind == "WEEKLY":
        return _weekly(start_date, step, parts[2], count)
    if kind == "MONTHLY" and len(parts) == 3:
        return _monthly_dom(start_date, step, int(parts[2]), count)
    if kind == "MONTHLY":
        return _monthly_nth(start_date, step, int(parts[2]), parts[3], count)
    return _yearly(start_date, step, parts[2], count)


_WEEKDAY = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}


def _daily(start: date, step: int, count: int) -> list[str]:
    found = []
    current = start
    while len(found) < count:
        found.append(current.isoformat())
        current += timedelta(days=step)
    return found


def _weekly(start: date, step: int, days: str, count: int) -> list[str]:
    weekdays = sorted(_WEEKDAY[code] for code in days.split(","))
    week_monday = start - timedelta(days=start.weekday())
    found = []
    week_index = 0
    while len(found) < count:
        monday = week_monday + timedelta(weeks=week_index)
        for weekday in weekdays:
            current = monday + timedelta(days=weekday)
            if current >= start:
                found.append(current.isoformat())
                if len(found) == count:
                    break
        week_index += step
    return found


def _shift_month(year: int, month: int, offset: int) -> tuple[int, int]:
    index = year * 12 + (month - 1) + offset
    return index // 12, index % 12 + 1


def _month_day(year: int, month: int, day: int) -> date | None:
    if day == -1:
        if month == 12:
            return date(year + 1, 1, 1) - timedelta(days=1)
        return date(year, month + 1, 1) - timedelta(days=1)
    try:
        return date(year, month, day)
    except ValueError:
        return None


def _monthly_dom(start: date, step: int, day: int, count: int) -> list[str]:
    found = []
    offset = 0
    while len(found) < count:
        year, month = _shift_month(start.year, start.month, offset)
        current = _month_day(year, month, day)
        if current is not None and current >= start:
            found.append(current.isoformat())
        offset += step
    return found


def _nth_weekday(year: int, month: int, n: int, weekday: int) -> date | None:
    first = date(year, month, 1)
    first_match = first + timedelta(days=(weekday - first.weekday()) % 7)
    if n == -1:
        current = first_match
        while True:
            nxt = current + timedelta(days=7)
            if nxt.month != month:
                return current
            current = nxt
    current = first_match + timedelta(weeks=n - 1)
    if current.month != month:
        return None
    return current


def _monthly_nth(start: date, step: int, n: int, code: str, count: int) -> list[str]:
    weekday = _WEEKDAY[code]
    found = []
    offset = 0
    while len(found) < count:
        year, month = _shift_month(start.year, start.month, offset)
        current = _nth_weekday(year, month, n, weekday)
        if current is not None and current >= start:
            found.append(current.isoformat())
        offset += step
    return found


def _yearly(start: date, step: int, mmdd: str, count: int) -> list[str]:
    month_text, day_text = mmdd.split("-")
    month, day = int(month_text), int(day_text)
    found = []
    year = start.year
    while len(found) < count:
        current = _month_day(year, month, day)
        if current is not None and current >= start:
            found.append(current.isoformat())
        year += step
    return found
